with s as (select id from skills where code = 'G8-S02'), a as (select id from assessments where kind = 'model' and form_label = 'bk-num-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'إذا كان أ و ب عددين صحيحين، وكان أ < 0 و ب > 0، فأي العبارات التالية صحيحة دائمًا؟', null, '[{"id": "a", "text": "أ + ب < 0"}, {"id": "b", "text": "أ × ب < 0"}, {"id": "c", "text": "أ − ب > 0"}, {"id": "d", "text": "|أ| < |ب|"}]'::jsonb, '{"value": "b"}'::jsonb, '["ضرب عدد سالب في عدد موجب يعطي عددًا سالبًا دائمًا.", "بقية العبارات تتوقف على قيم أ و ب."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 2، س 1'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 1 from a, qi;
with s as (select id from skills where code = 'G8-S04'), a as (select id from assessments where kind = 'model' and form_label = 'bk-num-1'),
