  select s.id, 'reasoning', 2, 'mcq', 'إذا كان س عددًا نسبيًا محصورًا بين 0 و 1 (0 < س < 1)، فأي القيم التالية هي الأكبر؟', null, '[{"id": "a", "text": "س"}, {"id": "b", "text": "س²"}, {"id": "c", "text": "1 ÷ س"}, {"id": "d", "text": "√س"}]'::jsonb, '{"value": "c"}'::jsonb, '["جرّب س = 0.25: س² = 0.0625، √س = 0.5، 1 ÷ س = 4.", "مقلوب عدد بين 0 و 1 أكبر من 1، فهو الأكبر."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 2، س 2'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 2 from a, qi;
