with s as (select id from skills where code = 'G8-S01'), a as (select id from assessments where kind = 'model' and form_label = 'bk-num-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'قطعة أرض مربعة مساحتها 144 م² خُصصت لقاعة رياضية، ويريد مهندس بناء ممر خارجي يحيط بها بحيث يتكوّن مربع كبير مساحته 256 م². ما عرض الممر من كل جانب؟', null, '[{"id": "a", "text": "2 م"}, {"id": "b", "text": "4 م"}, {"id": "c", "text": "8 م"}, {"id": "d", "text": "112 م"}]'::jsonb, '{"value": "a"}'::jsonb, '["طول ضلع القاعة √144 = 12 م، وطول ضلع المربع الكبير √256 = 16 م.", "الفرق 16 − 12 = 4 م يتوزع على جانبين، فعرض الممر 2 م."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 3، س 8 (بتصرف: حُوّل إلى اختيار من متعدد)'
