qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'أعلنت شركة اتصالات: من يشحن 50 ريالًا يحصل على 10 ريالات إضافية، ومن يشحن 100 ريال يحصل على 25 ريالًا إضافية. لدى خالد 200 ريال ويريد أكبر رصيد ممكن. ماذا يفعل؟', null, '[{"id": "a", "text": "يشحن 100 ريال مرتين، فيصبح رصيده 250 ريالًا"}, {"id": "b", "text": "يشحن 50 ريالًا أربع مرات، فيصبح رصيده 240 ريالًا"}, {"id": "c", "text": "يشحن 100 ريال مرة و 50 ريالًا مرتين، فيصبح رصيده 245 ريالًا"}, {"id": "d", "text": "الخيارات كلها تعطي الرصيد نفسه"}]'::jsonb, '{"value": "a"}'::jsonb, '["شحن 100 مرتين: 200 + 2 × 25 = 250.", "شحن 50 أربع مرات: 200 + 4 × 10 = 240.", "الخيار المختلط: 200 + 25 + 2 × 10 = 245."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 3، س 10 (بتصرف: حُوّل إلى اختيار من متعدد)'
