qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'رُتبت أعواد الثقاب في نمط على شكل بيوت كما في الشكل. إذا استمر النمط، فكم عودًا يلزم لصنع الشكل 10؟', '/booklet/a26-4.png', '[{"id": "a", "text": "60"}, {"id": "b", "text": "56"}, {"id": "c", "text": "51"}, {"id": "d", "text": "50"}]'::jsonb, '{"value": "c"}'::jsonb, '["الشكل 1: 6 أعواد، الشكل 2: 11، الشكل 3: 16، أي يزيد 5 كل مرة.", "الشكل ن يحتاج 5ن + 1، والشكل 10 يحتاج 51 عودًا."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 26، س 4'
