qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'المتتابعة الأولى: 5، 11، 17، 23، 29، ... تزداد بمقدار 6. والثانية: 3، 13، 23، 33، 43، ... تزداد بمقدار 10. العدد 23 موجود في كلتيهما. ما العدد التالي الذي يظهر في كلتا المتتابعتين؟', null, '[{"id": "a", "text": "47"}, {"id": "b", "text": "53"}, {"id": "c", "text": "59"}, {"id": "d", "text": "83"}]'::jsonb, '{"value": "b"}'::jsonb, '["الأعداد المشتركة تتكرر كل المضاعف المشترك الأصغر للعددين 6 و 10، وهو 30.", "23 + 30 = 53."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 26، س 5'
  from s returning id)
