qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'أطوال ظلال شجيرات الساعة 9 صباحًا: ارتفاع 28 سم ظله 21 سم، و 44 سم ظله 33، و 60 سم ظله 45، و 76 سم ظله 57. ما طول ظل شجيرة ارتفاعها 68 سم؟', null, '[{"id": "a", "text": "64"}, {"id": "b", "text": "57"}, {"id": "c", "text": "54"}, {"id": "d", "text": "51"}]'::jsonb, '{"value": "d"}'::jsonb, '["نسبة الظل إلى الارتفاع ثابتة: 21 ÷ 28 = ¾.", "¾ × 68 = 51 سم."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 27، س 6'
  from s returning id)
