qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'خزان يحتوي على 20 لترًا، ثم بدأ يُملأ بمعدل ثابت، وبعد دقيقتين أصبح فيه 30 لترًا، وبعد 4 دقائق 40 لترًا. أي وصف يمثل كمية الماء مع الزمن؟', null, '[{"id": "a", "text": "خط مستقيم يبدأ من (0، 0) ويزداد 5 لترات كل دقيقة"}, {"id": "b", "text": "خط مستقيم يبدأ من (0، 20) ويزداد 5 لترات كل دقيقة"}, {"id": "c", "text": "خط مستقيم يبدأ من (0، 20) ويزداد 10 لترات كل دقيقة"}, {"id": "d", "text": "خط مستقيم يبدأ من (0، 30) ويزداد 5 لترات كل دقيقة"}]'::jsonb, '{"value": "b"}'::jsonb, '["الكمية الابتدائية 20 لترًا، فالخط يبدأ من (0، 20).", "الزيادة 10 لترات في دقيقتين، أي 5 لترات في الدقيقة."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 27، س 7'
  from s returning id)
