qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'أشكال مقسمة إلى مثلثات صغيرة متطابقة: الشكل 1 فيه 2 مثلث، والشكل 2 فيه 18، والشكل 3 فيه 50. إذا استمر النمط، فكم مثلثًا صغيرًا في الشكل 7؟', '/booklet/a27-8.png', '[{"id": "a", "text": "338"}, {"id": "b", "text": "242"}, {"id": "c", "text": "98"}, {"id": "d", "text": "162"}]'::jsonb, '{"value": "a"}'::jsonb, '["الشكل ن مربع طول ضلعه (2ن − 1) وحدة، وكل مربع وحدة فيه مثلثان.", "عدد المثلثات 2(2ن − 1)²، وللشكل 7: 2 × 13² = 338."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 27، س 8 (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 8 from a, qi;
with s as (select id from skills where code = 'G8-S10'), a as (select id from assessments where kind = 'model' and form_label = 'bk-alg-4'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'لدى سارة ثلاث قطع معدنية متساوية الكتلة. يوضح الميزانان مقارنة كتلة قطعة واحدة بأثقال كتلتها 13 جرامًا، ثم كتلة القطع الثلاث بأثقال كتلتها 18 جرامًا. ما المتباينة التي تمثل القيم الممكنة لكتلة القطعة الواحدة (س)؟', '/booklet/a28-9.png', '[{"id": "a", "text": "6 < س < 13"}, {"id": "b", "text": "6 ≤ س ≤ 12"}, {"id": "c", "text": "س > 13"}, {"id": "d", "text": "س < 6"}]'::jsonb, '{"value": "a"}'::jsonb, '["الميزان الأول: كفة الأثقال (6 + 3 + 2 + 2 = 13 جرامًا) أثقل، إذن س < 13.", "الميزان الثاني: كفة القطع الثلاث أثقل من 18 جرامًا، إذن 3س > 18 ⇐ س > 6."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 28، س 9 (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 9 from a, qi;
with s as (select id from skills where code = 'G8-S11'), a as (select id from assessments where kind = 'model' and form_label = 'bk-alg-4'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'knowing', 1, 'mcq', 'العلاقة بين المسافة المقطوعة والتكلفة لسيارة أجرة: ص = 2½ س + 10، حيث س المسافة بالكيلومترات و ص التكلفة بالريالات. ماذا يمثل العدد 10؟', null, '[{"id": "a", "text": "الرسوم الأساسية الثابتة"}, {"id": "b", "text": "تكلفة كل كيلومتر"}, {"id": "c", "text": "المسافة المقطوعة"}, {"id": "d", "text": "التكلفة الكلية لرحلة 10 كم"}]'::jsonb, '{"value": "a"}'::jsonb, '["10 هو المقطع الصادي: قيمة ص عندما س = 0.", "أي ما يدفعه الراكب قبل قطع أي مسافة."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 29، س 10أ (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
