qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'العلاقة بين المسافة والتكلفة لسيارة أجرة: ص = 2½ س + 10. إذا بلغت تكلفة رحلة 35 ريالًا، فكم كيلومترًا قطعت السيارة؟', null, '[{"id": "a", "text": "10 كم"}, {"id": "b", "text": "14 كم"}, {"id": "c", "text": "18 كم"}, {"id": "d", "text": "25 كم"}]'::jsonb, '{"value": "a"}'::jsonb, '["35 = 2.5س + 10 ⇐ 2.5س = 25 ⇐ س = 10 كم."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 29، س 10ب (بتصرف: حُوّل إلى اختيار من متعدد)'
