qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'العلاقة الأصلية لتكلفة سيارة أجرة: ص = 2½ س + 10. إذا أصبحت تكلفة الكيلومتر 3 ريالات مع بقاء الرسوم الأساسية، فما العلاقة الجديدة وما التغير على رسمها البياني؟', null, '[{"id": "a", "text": "ص = 3س + 10، ويصبح الخط أشد انحدارًا مع بقاء المقطع الصادي"}, {"id": "b", "text": "ص = 3س + 10، ويرتفع الخط إلى الأعلى بموازاة الأصلي"}, {"id": "c", "text": "ص = 2½ س + 13، ويصبح الخط أشد انحدارًا"}, {"id": "d", "text": "ص = 3س + 13، ويبقى الميل كما هو"}]'::jsonb, '{"value": "a"}'::jsonb, '["تكلفة الكيلومتر هي الميل، فيصبح 3 بدلًا من 2½.", "الرسوم الأساسية (المقطع) تبقى 10، فيدور الخط حول النقطة (0، 10) ويزداد انحداره."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 29، س 10ج (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
