qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'طُلب تحديد زوايا مثلث أ ب ج بشروط: (1) ق∠أ = ق∠ب + ق∠ج، (2) ∠ب و ∠ج متتامتان، (3) قياس كل زاوية عدد زوجي. أي الخيارات يخالف أحد الشروط؟', null, '[{"id": "a", "text": "أ = 90°، ب = 50°، ج = 40°"}, {"id": "b", "text": "أ = 90°، ب = 60°، ج = 30°"}, {"id": "c", "text": "أ = 90°، ب = 65°، ج = 25°"}, {"id": "d", "text": "أ = 90°، ب = 70°، ج = 20°"}]'::jsonb, '{"value": "c"}'::jsonb, '["جميع الخيارات تحقق الشرطين الأول والثاني.", "65 و 25 عددان فرديان، فيخالف الخيار الثالث الشرط الثالث."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 37، س 3'
  from s returning id)
