with s as (select id from skills where code = 'G8-S13'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'في الشكل، مستقيمان متقاطعان، وإحدى الزوايا قياسها 40°. ما قيمة ع − ل ؟', '/booklet/g38-4.png', '[{"id": "a", "text": "100°"}, {"id": "b", "text": "80°"}, {"id": "c", "text": "60°"}, {"id": "d", "text": "40°"}]'::jsonb, '{"value": "a"}'::jsonb, '["ل متقابلة بالرأس مع الزاوية 40°، إذن ل = 40°.", "ع مكملة للزاوية 40°، إذن ع = 140°.", "ع − ل = 100°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 38، س 4'
  from s returning id)
