with s as (select id from skills where code = 'G8-S14'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'في المضلع الخماسي س ص ع ل م المتساوي الأضلاع، قياس كل من الزاويتين م و ص يساوي 120°، والزوايا الثلاث الأخرى متساوية. ما قياس الزاوية ج الموضحة في الشكل؟', '/booklet/g38-6.png', '[{"id": "a", "text": "40°"}, {"id": "b", "text": "35°"}, {"id": "c", "text": "30°"}, {"id": "d", "text": "20°"}]'::jsonb, '{"value": "a"}'::jsonb, '["مجموع زوايا الخماسي 540°، فكل من الزوايا الثلاث الأخرى (540 − 240) ÷ 3 = 100°.", "المثلث س م ل متطابق الضلعين وزاوية رأسه 120°، فكل من زاويتي قاعدته 30°، وكذلك المثلث س ص ع.", "ج = 100° − 30° − 30° = 40°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 38، س 6'
  from s returning id)
