with s as (select id from skills where code = 'G8-S14'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 1, 'mcq', 'سلم طوله 10 أقدام يستند إلى شجرة، وبُعد قاعدته عن الشجرة 6 أقدام. إلى أي ارتفاع على الشجرة وصل السلم؟', '/booklet/g38-7.png', '[{"id": "a", "text": "قدمان"}, {"id": "b", "text": "5 أقدام"}, {"id": "c", "text": "8 أقدام"}, {"id": "d", "text": "11 قدمًا"}]'::jsonb, '{"value": "c"}'::jsonb, '["السلم والشجرة والأرض تكوّن مثلثًا قائمًا، والسلم هو الوتر.", "الارتفاع = √(10² − 6²) = √64 = 8 أقدام."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 38، س 7'
  from s returning id)
