with s as (select id from skills where code = 'G8-S13'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'في سخان شمسي، الدعامة القائمة عمودية على الأرض (ق∠1 = 90°)، والزاوية بين اللوح الشمسي والأرض ق∠2 = 35°. ما قياس الزاوية الحادة المحصورة بين اللوح الشمسي والدعامة القائمة؟', '/booklet/g39-9.png', '[{"id": "a", "text": "55°"}, {"id": "b", "text": "35°"}, {"id": "c", "text": "65°"}, {"id": "d", "text": "125°"}]'::jsonb, '{"value": "a"}'::jsonb, '["اللوح والدعامة والأرض تكوّن مثلثًا.", "الزاوية المطلوبة = 180° − 90° − 35° = 55°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 39، س 9ج (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 8 from a, qi;
with s as (select id from skills where code = 'G8-S13'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'في الشكل: أب ∥ جـد، و ق∠ب = 100°، والمستقيم ي هـ ينصّف الزاوية ب ي جـ، والمستقيم ي هـ عمودي على المستقيم ي و. ما قياس كل من ∠ب ي و و ∠د ي و ؟', '/booklet/g41-1.png', '[{"id": "a", "text": "40°، 50°"}, {"id": "b", "text": "50°، 100°"}, {"id": "c", "text": "50°، 50°"}, {"id": "d", "text": "50°، 80°"}]'::jsonb, '{"value": "c"}'::jsonb, '["∠ب ي جـ تحالف ∠ب (زاويتان داخليتان في جهة واحدة)، إذن قياسها 180° − 100° = 80°، ونصفها ∠ب ي هـ = 40°.", "∠ب ي و = 90° − 40° = 50°.", "∠و ي جـ = 50° + 80° = 130°، إذن ∠د ي و = 180° − 130° = 50°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 41، س 1'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 1 from a, qi;
with s as (select id from skills where code = 'G8-S14'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'لوحة من الورق المقوى مستطيلة بعداها 75 سم و 50 سم، وفي منتصفها صورة مستطيلة بعداها 30 سم و 20 سم. ما مساحة المنطقة المحيطة بالصورة؟', null, '[{"id": "a", "text": "2500 سم²"}, {"id": "b", "text": "3150 سم²"}, {"id": "c", "text": "3750 سم²"}, {"id": "d", "text": "4200 سم²"}]'::jsonb, '{"value": "b"}'::jsonb, '["مساحة اللوحة 75 × 50 = 3750 سم²، ومساحة الصورة 30 × 20 = 600 سم².", "المنطقة المحيطة: 3750 − 600 = 3150 سم²."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 41، س 2أ'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 2 from a, qi;
with s as (select id from skills where code = 'G8-S14'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'لوحة بعداها 75 سم و 50 سم في منتصفها صورة بعداها 30 سم و 20 سم. إذا كُبّر كل من طول الصورة وعرضها بنسبة 50٪ مع بقاء أبعاد اللوحة، فما المساحة غير المغطاة من اللوحة؟', null, '[{"id": "a", "text": "2400 سم²"}, {"id": "b", "text": "2850 سم²"}, {"id": "c", "text": "3150 سم²"}, {"id": "d", "text": "2250 سم²"}]'::jsonb, '{"value": "a"}'::jsonb, '["أبعاد الصورة الجديدة: 45 سم و 30 سم، ومساحتها 1350 سم² (أي 2.25 مثل المساحة الأصلية).", "المساحة غير المغطاة: 3750 − 1350 = 2400 سم²، فقد نقصت 750 سم²."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 41، س 2ب (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 3 from a, qi;
with s as (select id from skills where code = 'G8-S14'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'لدى خالد بلاط على شكل شبه منحرف متطابق الضلعين، وصنع أربعة أشكال بوضع بلاطتين جنبًا إلى جنب كما في الشكل. أي الأشكال له أقل محيط؟', '/booklet/g41-3.png', '[{"id": "a", "text": "الشكل 1"}, {"id": "b", "text": "الشكل 2"}, {"id": "c", "text": "الشكل 3"}, {"id": "d", "text": "الشكل 4"}]'::jsonb, '{"value": "a"}'::jsonb, '["عند وضع بلاطتين متلاصقتين يختفي الضلع المشترك من المحيط مرتين.", "في الشكل 1 تتلاصق البلاطتان على القاعدة الكبرى (أطول ضلع)، فيكون المحيط أقل ما يمكن."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 41، س 3'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 4 from a, qi;
with s as (select id from skills where code = 'G8-S15'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'تشكّل دعامات أرجوحة مثلثًا متطابق الضلعين، حيث △أ ب جـ ≅ △هـ و د، و أب = أجـ = 150 سم، و بجـ = 75 سم، و ق∠هـ = 38°. ما طول هـو، وما قياس ∠أ جـ ب ؟', '/booklet/g42-4.png', '[{"id": "a", "text": "150 سم، 71°"}, {"id": "b", "text": "150 سم، 38°"}, {"id": "c", "text": "75 سم، 142°"}, {"id": "d", "text": "75/150 سم، 104°"}]'::jsonb, '{"value": "a"}'::jsonb, '["في المثلثين المتطابقين: هـو تناظر أب، إذن هـو = 150 سم، و ∠أ تناظر ∠هـ فقياسها 38°.", "المثلث أ ب جـ متطابق الضلعين، فزاويتا قاعدته متساويتان: (180° − 38°) ÷ 2 = 71°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 42، س 4'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 5 from a, qi;
with s as (select id from skills where code = 'G8-S13'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'في الشكل مستقيمان متوازيان، والزاوية بين المستقيم العلوي والضلع الأيمن 55°. ما قيمة س + ع ؟', '/booklet/g42-5.png', '[{"id": "a", "text": "55°"}, {"id": "b", "text": "100°"}, {"id": "c", "text": "115°"}, {"id": "d", "text": "125°"}]'::jsonb, '{"value": "d"}'::jsonb, '["زاوية المثلث عند القاعدة اليمنى تبادلية مع الزاوية 55°، فقياسها 55°.", "مجموع زوايا المثلث 180°، إذن س + ع = 180° − 55° = 125°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 42، س 5'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 6 from a, qi;
with s as (select id from skills where code = 'G8-S15'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'إذا كانت النقطة (7، 2) صورة النقطة (−7، 2) بانعكاس، فحول أي محور تم الانعكاس؟', null, '[{"id": "a", "text": "حول محور الصادات"}, {"id": "b", "text": "حول محور السينات"}, {"id": "c", "text": "حول المستقيم ص = س"}, {"id": "d", "text": "حول المستقيم ص = 2"}]'::jsonb, '{"value": "a"}'::jsonb, '["تغيرت إشارة الإحداثي السيني فقط وبقي الصادي كما هو.", "هذا انعكاس حول محور الصادات."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 42، س 6'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 7 from a, qi;
with s as (select id from skills where code = 'G8-S13'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'م (1، 2) و ن (5، 2) نقطتان في المستوى الإحداثي. يبحث رامي عن نقطة أ بحيث يكون △م ن أ متساوي الساقين. أي النقاط التالية يمكن أن تمثل أ؟', '/booklet/g42-7.png', '[{"id": "a", "text": "(3، 5)"}, {"id": "b", "text": "(3، 2)"}, {"id": "c", "text": "(5، 1)"}, {"id": "d", "text": "(1، 5)"}]'::jsonb, '{"value": "a"}'::jsonb, '["النقطة التي تبعد المسافة نفسها عن م و ن تقع على المستقيم س = 3 (العمود المنصّف للقطعة م ن).", "(3، 2) تقع على القطعة نفسها فلا تكوّن مثلثًا، أما (3، 5) فتكوّن مثلثًا متساوي الساقين."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 42، س 7'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 8 from a, qi;
with s as (select id from skills where code = 'G8-S15'), a as (select id from assessments where kind = 'model' and form_label = 'bk-geo-2'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'المضلعان أ ب جـ د و هـ و ز ي متشابهان، حيث أ ب = 12، أ د = 6، هـ ي = 4، و ز = 9. ما طولا بجـ و هـو ؟', '/booklet/g42-8.png', '[{"id": "a", "text": "بجـ = 13.5، هـو = 8"}, {"id": "b", "text": "بجـ = 6، هـو = 18"}, {"id": "c", "text": "بجـ = 13.5، هـو = 18"}, {"id": "d", "text": "بجـ = 9، هـو = 8"}]'::jsonb, '{"value": "a"}'::jsonb, '["معامل التشابه من الصغير إلى الكبير: أ د ÷ هـ ي = 6 ÷ 4 = 1.5.", "بجـ = 9 × 1.5 = 13.5، و هـو = 12 ÷ 1.5 = 8."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 42، س 8 (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
insert into assessment_items (assessment_id, question_id, position) select a.id, qi.id, 9 from a, qi;
