qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 1, 'mcq', 'في الشكل أ ب مستقيم، و ق∠أ جـ د = 5س، و ق∠ب جـ د = 4س. ما قياس الزاوية ب جـ د؟', '/booklet/g47-2.png', '[{"id": "a", "text": "20°"}, {"id": "b", "text": "40°"}, {"id": "c", "text": "80°"}, {"id": "d", "text": "100°"}]'::jsonb, '{"value": "c"}'::jsonb, '["الزاويتان متجاورتان على مستقيم: 5س + 4س = 180°، إذن س = 20°.", "ق∠ب جـ د = 4 × 20° = 80°."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 47، س 2'
  from s returning id)
