qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'لدى صالح وبدر قطعتان مستطيلتان متطابقتان من الورق، ولفّ كل منهما ورقته بطريقة مختلفة لتكوين أسطوانة كما في الشكل. أي الجمل التالية غير صحيحة؟', '/booklet/g50-2.png', '[{"id": "a", "text": "ارتفاع أسطوانة صالح أكبر من ارتفاع أسطوانة بدر"}, {"id": "b", "text": "قطر أسطوانة صالح أصغر من قطر أسطوانة بدر"}, {"id": "c", "text": "المساحة الجانبية لأسطوانة صالح تساوي المساحة الجانبية لأسطوانة بدر"}, {"id": "d", "text": "حجم أسطوانة صالح يساوي حجم أسطوانة بدر"}]'::jsonb, '{"value": "d"}'::jsonb, '["المساحة الجانبية في الحالتين هي مساحة الورقة نفسها.", "الحجم ط نق² ع يتأثر بنصف القطر أكثر من الارتفاع، فأسطوانة بدر (نصف قطرها أكبر) حجمها أكبر."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 50، س 2'
