with s as (select id from skills where code = 'G8-S16'), a as (select id from assessments where kind = 'model' and form_label = 'bk-data-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 2, 'mcq', 'يبين الرسم أعداد المسجلين في أربعة أندية: القراءة 18، الحساب 25، العلوم 22، البرمجة 30. أي العبارات صحيحة؟ (1) نادي البرمجة الأعلى تسجيلًا. (2) يزيد نادي البرمجة على نادي القراءة بمقدار 12. (3) نادي الحساب الأقل تسجيلًا. (4) مجموع ناديي الحساب والعلوم 57.', '/booklet/d57-2.png', '[{"id": "a", "text": "(1) و (2) فقط"}, {"id": "b", "text": "(1) و (3) فقط"}, {"id": "c", "text": "(2) و (4) فقط"}, {"id": "d", "text": "(3) و (4) فقط"}]'::jsonb, '{"value": "a"}'::jsonb, '["البرمجة 30 هي الأعلى، و 30 − 18 = 12.", "الأقل القراءة (18)، و 25 + 22 = 47 لا 57."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 57، س 2'
  from s returning id)
