  select s.id, 'applying', 1, 'mcq', 'يمثل الرسم عدد المشاركين في أربعة أنشطة مدرسية من فصلين: (أ) الفصل الأول و (ب) الفصل الثاني. في النشاط الثالث، كم يزيد عدد المشاركين من الفصل الثاني على عددهم من الفصل الأول؟', '/booklet/d58-4.png', '[{"id": "a", "text": "مشارك واحد"}, {"id": "b", "text": "مشاركان"}, {"id": "c", "text": "ثلاثة مشاركين"}, {"id": "d", "text": "خمسون مشاركًا"}]'::jsonb, '{"value": "b"}'::jsonb, '["في النشاط الثالث: الفصل الأول 24 والفصل الثاني 26.", "26 − 24 = 2."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 58، س 4'
  from s returning id)
