  select s.id, 'applying', 1, 'mcq', 'استُطلعت ميول 250 طالبًا نحو الأنشطة اللاصفية، ويبين التمثيل الدائري أن 30٪ منهم يفضلون الرياضة. كم عدد من يفضلون الرياضة؟', '/booklet/d58-5.png', '[{"id": "a", "text": "60"}, {"id": "b", "text": "70"}, {"id": "c", "text": "75"}, {"id": "d", "text": "80"}]'::jsonb, '{"value": "c"}'::jsonb, '["30٪ × 250 = 0.3 × 250 = 75."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 58، س 5'
  from s returning id)
