with s as (select id from skills where code = 'G8-S18'), a as (select id from assessments where kind = 'model' and form_label = 'bk-data-1'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'سأل معلم عشرة طلاب عن عدد الكتب التي قرأها كل منهم خلال شهر: قرأ طالب واحد كتابين، و 3 طلاب 3 كتب، و 4 طلاب 4 كتب، وطالبان 5 كتب. أي العبارات صحيحة؟ (1) عدد الطلاب 10. (2) منوال عدد الكتب 4. (3) وسيط عدد الكتب 3. (4) مدى عدد الكتب 5.', null, '[{"id": "a", "text": "(1) و (2) فقط"}, {"id": "b", "text": "(1) و (3) فقط"}, {"id": "c", "text": "(2) و (4) فقط"}, {"id": "d", "text": "(1) و (4) فقط"}]'::jsonb, '{"value": "a"}'::jsonb, '["عدد الطلاب 1 + 3 + 4 + 2 = 10، والمنوال 4 لأنه الأكثر تكرارًا.", "البيانات مرتبة: 2، 3، 3، 3، 4، 4، 4، 4، 5، 5، فالوسيط (4 + 4) ÷ 2 = 4، والمدى 5 − 2 = 3."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 58، س 6'
  from s returning id)
