  select s.id, 'reasoning', 2, 'mcq', 'تريد لجنة النشاط عرض توزيع ميزانية نشاط مدرسي كاملة على أربعة بنود (10٪، 20٪، 30٪، 40٪). اقترح أحدهم التمثيل بالخطوط. أي تقويم أدق لاقتراحه؟', '/booklet/d58-7.png', '[{"id": "a", "text": "التمثيل بالأعمدة هو التمثيل الوحيد الممكن"}, {"id": "b", "text": "القطاعات الدائرية أنسب؛ لأنها تُظهر الجزء من الكل"}, {"id": "c", "text": "التمثيل بالخطوط أنسب لعدم وجود زمن"}, {"id": "d", "text": "التمثيل بالنقاط المبعثرة هو الأنسب"}]'::jsonb, '{"value": "b"}'::jsonb, '["البيانات أجزاء من كل (مجموعها 100٪).", "القطاعات الدائرية تُظهر نصيب كل بند من الكل، والخطوط تناسب التغير عبر الزمن."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 58، س 7'
  from s returning id)
