  select s.id, 'applying', 2, 'mcq', 'أعداد مسائل التدريب في أربعة أسابيع: 18، 24، 21، 27. إذا أصبح عدد مسائل الأسبوع الأول 22 بدلًا من 18، فكيف يتغير مدى البيانات؟', null, '[{"id": "a", "text": "يقل من 9 إلى 6"}, {"id": "b", "text": "يزيد من 9 إلى 13"}, {"id": "c", "text": "لا يتغير"}, {"id": "d", "text": "يقل من 9 إلى 5"}]'::jsonb, '{"value": "a"}'::jsonb, '["المدى الأصلي 27 − 18 = 9.", "بعد التغيير تصبح أصغر قيمة 21، فالمدى 27 − 21 = 6."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 59، س 8 (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
