qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'لخّص معلم نتائج فصلين: الفصل أ: المتوسط 20 والوسيط 20، الفصل ب: المتوسط 20 والوسيط 16. أي العبارات تدعمها البيانات؟ (1) متوسط الدرجات متساوٍ في الفصلين. (2) قد تكون في الفصل ب درجات مرتفعة أثرت في المتوسط. (3) جميع درجات الفصلين متساوية. (4) وسيط الفصل أ يساوي 16.', null, '[{"id": "a", "text": "(1) و (2) فقط"}, {"id": "b", "text": "(1) و (3) فقط"}, {"id": "c", "text": "(2) و (4) فقط"}, {"id": "d", "text": "(1) و (4) فقط"}]'::jsonb, '{"value": "a"}'::jsonb, '["المتوسطان متساويان (20).", "في الفصل ب المتوسط أكبر من الوسيط، وهذا يشير إلى قيم مرتفعة ترفع المتوسط."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 63، س 6'
  from s returning id)
