with s as (select id from skills where code = 'G8-S18'), a as (select id from assessments where kind = 'model' and form_label = 'bk-data-3'),
qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'applying', 3, 'mcq', 'الزمن (بالدقائق) الذي استغرقه سبعة طلاب لإنجاز مهمة: 16، 13، 14، 42، 15، 12، 14. ما المتوسط والوسيط؟ وما المتوسط بعد حذف الزمن 42؟', null, '[{"id": "a", "text": "المتوسط 18، الوسيط 14، والمتوسط بعد الحذف 14"}, {"id": "b", "text": "المتوسط 14، الوسيط 18، والمتوسط بعد الحذف 18"}, {"id": "c", "text": "المتوسط 18، الوسيط 15، والمتوسط بعد الحذف 13"}, {"id": "d", "text": "المتوسط 16، الوسيط 14، والمتوسط بعد الحذف 14"}]'::jsonb, '{"value": "a"}'::jsonb, '["المجموع 126، والمتوسط 126 ÷ 7 = 18. والقيم مرتبة: 12، 13، 14، 14، 15، 16، 42، فالوسيط 14.", "بعد حذف 42: 84 ÷ 6 = 14، فالقيمة المتطرفة كانت ترفع المتوسط، والوسيط أنسب لوصف الزمن المعتاد."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 63، س 8 (بتصرف: حُوّل إلى اختيار من متعدد)'
