qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 3, 'mcq', 'درجات أربعة طلاب: 14، 18، 20، 28. إذا صحح المعلم الدرجة 28 إلى 20، فأي المقياسين يتأثر أكثر: المتوسط أم الوسيط؟', null, '[{"id": "a", "text": "المتوسط؛ ينخفض من 20 إلى 18 ويبقى الوسيط 19"}, {"id": "b", "text": "الوسيط؛ ينخفض من 19 إلى 18 ويبقى المتوسط 20"}, {"id": "c", "text": "يتأثران بالمقدار نفسه"}, {"id": "d", "text": "لا يتأثر أي منهما"}]'::jsonb, '{"value": "a"}'::jsonb, '["قبل التصحيح: المتوسط 80 ÷ 4 = 20، والوسيط (18 + 20) ÷ 2 = 19.", "بعد التصحيح: المتوسط 72 ÷ 4 = 18، والوسيط ما زال (18 + 20) ÷ 2 = 19.", "المتوسط يعتمد على كل القيم، فيتأثر بتغير القيمة الكبرى."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 64، س 10 (بتصرف: حُوّل إلى اختيار من متعدد)'
  from s returning id)
