qi as (insert into questions (skill_id, cognitive, difficulty, qtype, prompt, media_url, options, correct_answer, solution_steps, status, bank, source_label)
  select s.id, 'reasoning', 2, 'mcq', 'يلخص التمثيل بالصندوق وطرفيه درجات فصلين أ و ب في مهمة أدائية. أي العبارات صحيحة؟ (1) وسيط الدرجات متساوٍ في الفصلين. (2) درجات الفصل ب أكثر انتشارًا. (3) درجات الفصل أ أكثر انتشارًا. (4) مدى الدرجات متساوٍ في الفصلين.', '/booklet/d65-2.png', '[{"id": "a", "text": "(1) و (2) فقط"}, {"id": "b", "text": "(1) و (3) فقط"}, {"id": "c", "text": "(2) و (4) فقط"}, {"id": "d", "text": "(3) و (4) فقط"}]'::jsonb, '{"value": "a"}'::jsonb, '["خط الوسيط في الصندوقين عند القيمة نفسها (15).", "صندوق الفصل ب وطرفاه أطول، فمداه ومداه الربيعي أكبر، أي أن بياناته أكثر انتشارًا."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 65، س 2'
