  select s.id, 'reasoning', 2, 'mcq', 'درجتا طالبين في المجموعة أ: 12، 12، وفي المجموعة ب: 8، 16. قال طالب: «تشتت المجموعتين متساوٍ؛ لأن متوسط كل منهما 12». ما الخطأ في استدلاله؟', null, '[{"id": "a", "text": "افترض أن تساوي المتوسطين يعني تساوي تشتت البيانات"}, {"id": "b", "text": "حسب مدى المجموعة ب بصورة صحيحة"}, {"id": "c", "text": "متوسطا المجموعتين مختلفان"}, {"id": "d", "text": "لا يمكن مقارنة مجموعتين من قيمتين"}]'::jsonb, '{"value": "a"}'::jsonb, '["المتوسطان متساويان فعلًا (12).", "لكن مدى المجموعة أ صفر ومدى المجموعة ب 8، فالتشتت مختلف."]'::jsonb, 'published', 'library', 'كراسة تدريبات الصف الثاني متوسط (إعداد معلمات الرياضيات)، ص 65، س 3'
